// GetMessageTypeInfo returns the message type info for a given namespace/message combination
func GetMessageTypeInfo(namespace, messageName string) (MessageTypeInfo, bool) {
	key := namespace + "/" + messageName
	info, exists := MessagesTypes[key]
	return info, exists
}

// GetMessageTypeInfoByFullType returns the message type info for a given full message type (namespace/message)
func GetMessageTypeInfoByFullType(fullType string) (MessageTypeInfo, bool) {
	info, exists := MessagesTypes[fullType]
	return info, exists
}

// IsValidMessageType checks if a given message type is valid
func IsValidMessageType(messageType string) bool {
	_, exists := MessagesTypes[messageType]
	return exists
}

// GetNamespaceFromMessageType extracts the namespace from a full message type
func GetNamespaceFromMessageType(messageType string) string {
	if info, exists := MessagesTypes[messageType]; exists {
		return info.Namespace
	}
	return ""
}

// GetMessageNameFromMessageType extracts the message name from a full message type
func GetMessageNameFromMessageType(messageType string) string {
	if info, exists := MessagesTypes[messageType]; exists {
		return info.Name
	}
	return ""
}

