// GetAttributeTypeInfo returns the attribute type info for a given namespace/attribute combination
func GetAttributeTypeInfo(namespace, attributeName string) (AttributeTypeInfo, bool) {
	key := namespace + "/" + attributeName
	info, exists := AttributesTypes[key]
	return info, exists
}

// GetAttributeTypeInfoByFullType returns the attribute type info for a given full attribute type (namespace/attribute)
func GetAttributeTypeInfoByFullType(fullType string) (AttributeTypeInfo, bool) {
	info, exists := AttributesTypes[fullType]
	return info, exists
}

// IsValidAttributeType checks if a given attribute type is valid
func IsValidAttributeType(attributeType string) bool {
	_, exists := AttributesTypes[attributeType]
	return exists
}

// GetNamespaceFromAttributeType extracts the namespace from a full attribute type
func GetNamespaceFromAttributeType(attributeType string) string {
	if info, exists := AttributesTypes[attributeType]; exists {
		return info.Namespace
	}
	return ""
}

// GetAttributeNameFromAttributeType extracts the attribute name from a full attribute type
func GetAttributeNameFromAttributeType(attributeType string) string {
	if info, exists := AttributesTypes[attributeType]; exists {
		return info.Name
	}
	return ""
}
